<?php use App\Models\Community; $title = 'Global Dawah Stories'; $active = 'stories'; $cont = fn($c) => $c ?: 'Global'; ?>
<div class="hero"><div><div class="eyebrow">Live from every corner of the world</div><h1>Global Dawah Stories</h1><p>Read updates, impact stories, and volunteer journeys from around the world.</p></div><span class="grow"></span><a class="btn btn-accent" href="<?= e(url('/stories/submit')) ?>"><?= icon('edit', '', 14) ?> Share Your Story</a></div>
<?php if ($featured && !$q && !$continent && !$category): ?>
<div class="section-head"><div class="section-title"><span class="section-num"><?= icon('star', '', 14) ?></span><h2>Featured Stories</h2></div></div>
<div class="grid-3" style="margin-bottom:22px"><?php foreach ($featured as $s): ?><a class="region-card story-card" href="<?= e(url('/stories/' . $s['id'])) ?>"><?php if ($s['image_doc_id'] || $s['image_url']): ?><img class="event-cover" src="<?= e($s['image_doc_id'] ? url('/documents/' . $s['image_doc_id']) : $s['image_url']) ?>" alt=""><?php endif; ?><div style="padding:14px 16px"><span class="chip"><?= e($s['category'] ?: 'Story') ?></span> <span class="chip" style="border-color:var(--accent)">Featured</span><h3 style="margin:8px 0 4px"><?= e($s['title']) ?></h3><p class="small muted"><?= e(mb_substr((string) $s['excerpt'], 0, 140)) ?></p><small class="muted"><?= icon('globe', '', 11) ?> <?= e($cont($s['continent'])) ?><?= $s['country'] ? ' · ' . e($s['country']) : '' ?></small></div></a><?php endforeach; ?></div>
<?php endif; ?>
<form class="table-toolbar" method="get" action="<?= e(url('/stories')) ?>">
  <input class="input" name="q" value="<?= e($q) ?>" placeholder="Search stories…">
  <select name="continent"><option value="">All Continents</option><?php foreach (Community::CONTINENTS as $c): ?><option <?= $continent === $c ? 'selected' : '' ?>><?= e($c) ?></option><?php endforeach; ?></select>
  <select name="category"><option value="">All Stories</option><?php foreach (Community::STORY_CATEGORIES as $c): ?><option <?= $category === $c ? 'selected' : '' ?>><?= e($c) ?></option><?php endforeach; ?></select>
  <button class="btn btn-sm btn-dark">Filter</button><span class="muted small"><?= count($rows) ?> stories</span>
</form>
<?php if (!$rows): ?><div class="card"><p class="empty">No stories found. Try a different filter.</p></div><?php else: ?>
<div class="grid-3"><?php foreach ($rows as $s): ?><a class="region-card story-card" href="<?= e(url('/stories/' . $s['id'])) ?>"><?php if ($s['image_doc_id'] || $s['image_url']): ?><img class="event-cover" src="<?= e($s['image_doc_id'] ? url('/documents/' . $s['image_doc_id']) : $s['image_url']) ?>" alt=""><?php else: ?><div class="event-cover is-blank"><?= icon('globe', '', 30) ?></div><?php endif; ?><div style="padding:14px 16px"><span class="chip"><?= e($s['category'] ?: 'Story') ?></span><?php if ($s['featured']): ?> <span class="chip" style="border-color:var(--accent)">Featured</span><?php endif; ?><br><small class="muted"><?= e($cont($s['continent'])) ?><?= $s['country'] ? ' · ' . e($s['country']) : '' ?></small><h3 style="margin:6px 0 4px"><?= e($s['title']) ?></h3><p class="small muted"><?= e(mb_substr((string) $s['excerpt'], 0, 160)) ?></p><small class="muted"><?= e($s['author']) ?><?= $s['published_date'] ? ' · ' . e(fmt_date($s['published_date'])) : '' ?></small></div></a><?php endforeach; ?></div>
<?php endif; ?>
<div class="card" style="margin-top:22px;text-align:center"><h2>Share Your Story</h2><p class="muted">Are you a volunteer with an inspiring story? Submit it and earn the Storyteller badge.</p><a class="btn btn-primary" href="<?= e(url('/stories/submit')) ?>">Submit Your Story</a></div>
